import React, { useState, useEffect, useRef } from "react";
import "./Accordion.scss";
import { MpaIcon } from "../icon";
import { SvgMpaIcon } from "../../assets/icons/index";
import { Button } from "../button";

export interface AccordionItem {
  id: string;
  title: string;
  leadingIcon?: keyof typeof SvgMpaIcon | string;
  content: React.ReactNode;
  open?: boolean;
}

export interface AccordionProps {
  /**
   * Unique identifier for the accordion component
   */
  // id: string;
  /**
   * Accordion Data
  */
  accordion: AccordionItem[];

  /**
   * Determine show/ hide the leading icon
   */
  showLeadingIcon?: boolean;

  /**
   * Determine show/ hide the trailing icon
   */
  showTrailingIcon?: boolean;

  /**
   * Allow multiple tabs to stay open at the same time
   */
  allowMultipleOpen?: boolean;

  /**
  * Controls whether the first item remains open at all times.
  */
  firstItemAlwaysOpen?: boolean;

   /**
  * Controls whether the show expand all button.
  */
  showExpandAll?: boolean;



}

export const Accordion: React.FC<AccordionProps> = ({
  // id,
  accordion,
  showLeadingIcon = true,
  showTrailingIcon = true,
  allowMultipleOpen = false,
  firstItemAlwaysOpen = true,
  showExpandAll = false,

}) => {

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();

    }
  };

  const [openItemIds, setOpenItemIds] = useState<string[]>([]);
  const [expandAll, setExpandAll] = useState(false); 

 

  const handleToggle = (id: string) => {
    if (allowMultipleOpen) {
      setOpenItemIds((prev) =>
        prev.includes(id) ? prev.filter((itemId) => itemId !== id) : [...prev, id]
      );
    } else {
      setOpenItemIds((prev) => (prev.includes(id) ? [] : [id]));
    }
  };

  const handleExpandAll = () => {
  if (expandAll) {
    // Collapse all (respect firstItemAlwaysOpen)
    if (firstItemAlwaysOpen && accordion.length > 0) {
      setOpenItemIds([accordion[0].id]);
    } else {
      setOpenItemIds([]);
    }
  } else {
    // Expand all
    const allIds = accordion.map((item) => item.id);
    setOpenItemIds(allIds);
  }

  // Toggle state
  setExpandAll(!expandAll);
};

  useEffect(() => {
    if (firstItemAlwaysOpen && accordion.length > 0) {
      setOpenItemIds([accordion[0].id]);
      
    }
    const activeIds = accordion .filter((item) => item.open).map((item) => item.id);
    if (activeIds.length > 0) {
      setOpenItemIds(activeIds);
    }
  }, [firstItemAlwaysOpen, accordion]);



  

  useEffect(() => {
    if (!window.ResizeObserver) return;

    const observers: Record<string, ResizeObserver> = {};

    accordion.forEach((item) => {
      const contentEl = contentRefs.current[item.id];
      if (contentEl) {
        const observer = new ResizeObserver(() => {
          if (openItemIds.includes(item.id)) {
            contentEl.style.maxHeight = contentEl.scrollHeight + "px";
          } else {
            contentEl.style.maxHeight = "0px";
          }
        });

        observer.observe(contentEl);
        observers[item.id] = observer;

        // Set initial height based on state
        if (openItemIds.includes(item.id)) {
          contentEl.style.maxHeight = contentEl.scrollHeight + "px";
        } else {
          contentEl.style.maxHeight = "0px";
        }
      }
    });

    return () => {
      Object.values(observers).forEach((observer) => observer.disconnect());
    };
  }, [openItemIds, accordion]);





  const contentRefs = useRef<Record<string, HTMLDivElement | null>>({});

  return (

    <>
    { showExpandAll &&
      <div className="accordion-controls">
        <Button
          btnType="text"
          id="btnExpandAll"
          label={expandAll ? "– Collapse All" : "+ Expand All"}
          size="large"
          onClick={handleExpandAll}
        />
      </div>
      }
      <div className="mpa-accordion">
        {accordion.map((item) => {
          const isOpen = openItemIds?.includes(item.id);

          return (
            <div key={item.id}>
              <div
                // id={id}
                className={`accordion-header ${isOpen ? 'open' : ''}`}
                role="button"
                tabIndex={0}
                onClick={() => handleToggle(item.id)}
                onKeyDown={(e) => handleKeyDown(e)}
                aria-expanded={isOpen}
                aria-controls={`${item.id}-content`}
              >
                <span className="accorion-title">
                  <span className={`leading-icon ${showLeadingIcon ? 'visible' : ''}`} >
                    {/* <MpaIcon iconName={item.leadingIcon} /> */}
                    {showLeadingIcon && item.leadingIcon ? (
                        <MpaIcon iconName={item.leadingIcon} />
                    ) : (
                        <div></div>
                    )}
                  </span>
                  {item.title}
                </span>

                <span className={`trailing-icon ${isOpen ? 'rotate' : ''} ${showTrailingIcon ? 'visible' : ''}`} >
                  <MpaIcon iconName={'ChevronDown'} />
                </span>

              </div>

              <div id={`${item.id}-content`}
                ref={(el) => (contentRefs.current[item.id] = el)}
                className={`accordion-content ${isOpen ? 'open' : ''}`}>
                <div className="accordion-inner">{item.content}</div>
              </div>
            </div>
          );
        })}
      </div>
    </>
  );
};

export default Accordion;